const row = $input.first().json;

const audience = row.audience_summary || {};
const data = row.data_intake || {};
const funnel = row.interview_funnel || {};
const quality = row.observation_quality || {};
const signals = row.signal_summary || {};
const topContributors = Array.isArray(row.top_contributors) ? row.top_contributors : [];
const distribution = row.participant_distribution || {};
const bottlenecks = row.bottlenecks || {};
const behaviors = Array.isArray(row.emerging_behaviors) ? row.emerging_behaviors : [];
const themes = Array.isArray(row.repeated_themes) ? row.repeated_themes : [];
const reflection = row.reflection_coach_metrics || {};

function n(value) {
  return value === null || value === undefined ? 0 : Number(value);
}

function display(value) {
  return String(value ?? 'unknown')
    .replace(/_/g, ' ')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[\*[\]]/g, '')
    .trim();
}

function listTop(items, labelKey = 'signal_name', limit = 3) {
  if (!Array.isArray(items) || items.length === 0) return 'none';
  return items
    .slice(0, limit)
    .map(item => display(item[labelKey] || item.theme || item.behavior || 'unknown') + ' (' + item.count + ')')
    .join(', ');
}

function numberedContributors(items) {
  if (!Array.isArray(items) || items.length === 0) return ['- none'];
  return items.slice(0, 5).map((item, index) =>
    (index + 1) + '. ' + display(item.participant || item.person_id) + ' — ' + n(item.count)
  );
}

function statusLine(statusCounts) {
  if (!statusCounts || Object.keys(statusCounts).length === 0) return 'none';
  return Object.entries(statusCounts).map(([key, value]) => display(key) + ': ' + value).join(', ');
}

function stageLine(stageCounts) {
  const stages = ['new','waiting_q1','waiting_q2','waiting_q3','waiting_q4','analysis','completed'];
  const counts = stageCounts || {};
  return stages.map(stage => display(stage) + ': ' + (counts[stage] ?? 0)).join(', ');
}

function percent(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return '0%';
  return Math.round(num) + '%';
}

function mostActiveLine(value) {
  if (!value || !value.participant) return 'none';
  return display(value.participant) + ' (' + n(value.entries) + ')';
}

function reflectionLines(metrics) {
  if (!metrics.tracked) return ['- Reflection metrics not yet tracked.'];
  return [
    '- confirmations sent: ' + n(metrics.confirmations_sent),
    '- questions sent: ' + n(metrics.questions_sent),
    '- missions sent: ' + n(metrics.missions_sent),
    '- deep reflections sent: ' + n(metrics.deep_reflections_sent)
  ];
}

function getChatId() {
  try {
    return $('Telegram Trigger').first().json.message.chat.id;
  } catch (e) {
    return 300628321;
  }
}

const behaviorSource = behaviors.length > 0 ? behaviors : themes;
const behaviorSubtitle = behaviors.length > 0 ? '' : '(raw observation patterns)';
const behaviorLine = listTop(behaviorSource, behaviors.length > 0 ? 'behavior' : 'theme', 5);

const bottleneckPairs = Object.entries(bottlenecks).map(([key, value]) => [key, n(value)]).sort((a, b) => b[1] - a[1]);
const mainBottleneck = bottleneckPairs.find(([, value]) => value > 0);
const mainBottleneckText = mainBottleneck ? display(mainBottleneck[0]) + ': ' + mainBottleneck[1] : 'no visible bottleneck';

const lines = [
  'BrainCoach Intelligence Monitor MVP-1.1',
  new Date().toISOString(),
  '',
  '0. Audience Summary',
  '- unique participants: ' + n(audience.unique_participants),
  '- new participants today: ' + n(audience.new_participants_today),
  '- most active participant: ' + mostActiveLine(audience.most_active_participant),
  '- avg entries per participant: ' + (audience.avg_entries_per_participant ?? '0'),
  '',
  '1. Data Intake Summary',
  '- tracker_entries total: ' + n(data.tracker_entries_total),
  '- tracker_entries today: ' + n(data.tracker_entries_today),
  '- tracker_entries last 24h: ' + n(data.tracker_entries_last_24h),
  '- observations total: ' + n(data.observations_total),
  '- observations today: ' + n(data.observations_today),
  '- signal_candidates total: ' + n(data.signal_candidates_total),
  '- signal_candidates today: ' + n(data.signal_candidates_today),
  '',
  '2. Interview Funnel',
  '- parent_interviews total: ' + n(funnel.parent_interviews_total),
  '- started: ' + n(funnel.started),
  '- in_progress: ' + n(funnel.in_progress),
  '- completed: ' + n(funnel.completed),
  '- abandoned: ' + n(funnel.abandoned),
  '- active conversations: ' + stageLine(funnel.active_conversations_by_stage),
  '',
  '3. Observation Quality',
  '- observations: ' + n(quality.observations_total),
  '- signal candidates: ' + n(quality.signal_candidates_total),
  '- conversion: ' + percent(quality.observation_signal_conversion_pct),
  '',
  '4. Signal Summary',
  '- top signal today: ' + listTop(signals.top_signal_name_today),
  '- top signal all time: ' + listTop(signals.top_signal_name_all_time),
  '- average confidence: ' + (signals.average_confidence ?? 'n/a'),
  '- low-confidence count: ' + n(signals.low_confidence_count),
  '- statuses: ' + statusLine(signals.candidate_status_counts),
  '',
  '5. Top Contributors',
  ...numberedContributors(topContributors),
  '',
  '6. Participant Distribution',
  '- participants with 1 entry: ' + n(distribution.participants_with_1_entry),
  '- participants with 2-5 entries: ' + n(distribution.participants_with_2_5_entries),
  '- participants with >5 entries: ' + n(distribution.participants_with_gt_5_entries),
  '',
  '7. System Bottlenecks',
  '- observations without signal candidates: ' + n(bottlenecks.observations_without_signal_candidates),
  '- signal candidates without observation_id: ' + n(bottlenecks.signal_candidates_without_observation_id),
  '- conversations stuck > 6h: ' + n(bottlenecks.conversations_stuck_over_6h),
  '- interviews started but no responses: ' + n(bottlenecks.interviews_started_no_responses),
  '- errors today: ' + n(bottlenecks.errors_today),
  '',
  '8. Emerging Behaviors',
  ...(behaviorSubtitle ? [behaviorSubtitle] : []),
  '- grouped patterns: ' + behaviorLine,
  '',
  'Reflection Coach Metrics',
  ...reflectionLines(reflection),
  '',
  '9. Daily Intelligence Draft',
  '- Today the system is collecting: ' + n(data.tracker_entries_today) + ' tracker entries, ' + n(data.observations_today) + ' observations, ' + n(data.signal_candidates_today) + ' signal candidates.',
  '- Audience: ' + n(audience.unique_participants) + ' participants; most active: ' + mostActiveLine(audience.most_active_participant) + '.',
  '- Observation quality: ' + percent(quality.observation_signal_conversion_pct) + ' observation to signal conversion.',
  '- Emerging behaviors: ' + behaviorLine + '.',
  '- Possible bottleneck: ' + mainBottleneckText + '.',
  '- Manual review: inspect low-confidence candidates, participant concentration, and observation to signal gaps.'
];

return [{
  json: {
    report_text: lines.join('\n'),
    chat_id: getChatId(),
    run_at: row.run_at,
    read_only: true
  }
}];
